#ifndef SPOTIC_PROTOCOL_AP_HANDSHAKE_H
#define SPOTIC_PROTOCOL_AP_HANDSHAKE_H
#include "ap_packet.h"
#include "crypto.h"

#define AP_HANDSHAKE_MAX ((size_t)65536)
#define AP_HELLO_MAX ((size_t)512)
typedef struct ApHandshake {
    CryptoDh *dh; /* Borrowed; owner clears at completion/cancellation. */
    uint8_t transcript[AP_HANDSHAKE_MAX + AP_HELLO_MAX];
    uint8_t reply[64];
    size_t hello_bytes, received, expected, reply_bytes;
    bool started, complete;
    ApResult failure;
} ApHandshake;

/* Start at {0}. dh must already be generated by CNG and nonce generated by crypto_random.
 * Inputs are explicit to permit independent deterministic fixture replay.
 * No production key/nonce override or alternate signature-verification path. */
ApResult ap_handshake_begin(ApHandshake *handshake, CryptoDh *dh,
    const uint8_t nonce[16], uint64_t version);
ApResult ap_handshake_feed(ApHandshake *handshake, const void *bytes, size_t size,
    size_t *consumed, CryptoSessionKeys *keys);
void ap_handshake_clear(ApHandshake *handshake);
#endif
